import{_ as r,C as t,o as s,c as a,j as e,a as n,E as i,a5 as l}from"./chunks/framework.DjDdFq93.js";const f=JSON.parse('{"title":"九十秒","description":"","frontmatter":{"title":"九十秒","prev":{"text":"失误","link":"/books/super-supportive/02"},"next":{"text":"返回作品目录","link":"/books/super-supportive/"}},"headers":[],"relativePath":"books/super-supportive/03.md","filePath":"books/super-supportive/03.md"}'),u={name:"books/super-supportive/03.md"};function d(c,p,_,k,v,b){const o=t("ReadingTools");return s(),a("div",null,[p[0]||(p[0]=e("h1",{id:"九十秒",tabindex:"-1"},[n("九十秒 "),e("a",{class:"header-anchor",href:"#九十秒","aria-label":'Permalink to "九十秒"'},"​")],-1)),p[1]||(p[1]=e("p",{class:"book-author"},"Super Supportive · Sleyca · 中文译文",-1)),i(o,{id:"super-supportive/03",markable:""}),p[2]||(p[2]=l('<div class="chapter-body"><p>时间过去了。事情也变了。</p><p>社会服务部门终于找到了奥尔登那位行踪不定的姨妈康妮，于是两个人成了一家人。他们彼此关爱，可这段关系的健全与庇护，远远比不上他和父母之间的关系。用奥尔登一位小学老师非常委婉的说法，康妮姨妈的养育方式不太传统。</p><p>他十一岁那年，一场比赛结束后，棒球教练在球员席后面嚼着一大团口香糖，说话就没那么客气了。“听着，奥尔登，”他嚼得吧唧吧唧响，“你这孩子脑子很清楚，所以我就直说了。在你们这段关系里，居然要由你当大人，这不对。那女人脑袋里螺帽乱滚，还有一群松鼠追着跑。”</p><p>奥尔登皱着眉，低头看自己用鞋在红土上蹭出来的一个小坑。他不喜欢别人说姨妈的坏话，却也很难反驳。“她迟早会来接我的。您不用陪我等。”</p><p>“孩子，上场比赛她把你丢在这里，一直等到文体中心都关门了。别以为我没听说。”</p><p>奥尔登琢磨，要不要提一提，他已经用姨妈的姓名和证件号码，在手机上装了个应用，这样实在有需要时，就能租用城里那些只向成年人开放的电动滑板车。不过，那也许只会证明教练说得没错。</p><p>于是，他们一起等。她也确实来了。那天下午只迟到了一小时，拿堵车当理由，汽车后座上还放着六品脱融化了的冰淇淋。</p><p>没关系。</p><p>他们把冰淇淋倒掉，又买了些新的当晚饭。之后，康妮姨妈当时上班的那家美发店里的几位朋友，带着比萨、啤酒和震耳欲聋的音乐，来到了他们家。临时聚会闹得乱糟糟、令人不自在之后，奥尔登便消失在自己房间里。</p><p>他戴上最喜欢的那副耳机，在电脑上打了一会儿游戏，然后开始写作业。</p><p>只是阅读——一篇简明历史，讲系统怎样降临，又如何改变了地球。里面没有多少新知识。</p><p>阿尔托纳人将系统引入地球，就像过去在其他许多星球上做过的那样。作为换取超能力、奥秘知识和科技的条件，人类必须同意，在受到召唤时帮助阿尔托纳人。很多人接受了这项提议，于是，第一批超人类诞生了。</p><p>那是七十年前，二十世纪六十年代初的事。几乎所有人都认为，这对人类来说是笔好交易。大多数人觉得，没有阿尔托纳人，地球甚至可能连互联网和手机都没有。而当这些来自外星的地球恩人召唤英雄时，阿尔托纳人也很公平。他们有时会派下困难的任务，但总会提供与任务相当的报酬。</p><p>这些奥尔登早就知道了。阅读作业的末尾，在线课本附了一项面向所有读者的投票，问你想不想拥有超能力。他只犹豫了一下，就点了“想”。</p><p>你属于多数派！屏幕宣布。阅读本章的同学中，有 96% 也表示想拥有超能力。</p><p>你们都超级勇敢。成为英雄，是一项重要的工作。</p><p>但你知道吗？地球上只有 0.07% 的人，会得到签订《跨维度战士契约》的机会。（提醒：这是系统的正式名称，小测验可能会考。）</p><p>也就是大约 760 万名超人类。听上去是个很大的数字，但这也意味着，想拥有超能力的人里，有超过 105 亿人永远连机会都得不到。</p><p>好多人要失望了，奥尔登想，自己也失望得很。</p><p>他回答了几道阅读理解题，得了 10/10 分，屏幕上绽开一阵烟花。</p><p>到了午夜，家里仍然很吵，他只好放弃睡觉。他偷偷溜到小客厅，拿了一片冷比萨，又回到书桌前，做起时断时续的那个爱好。调查那场意外。</p><p>三年的时间让许多感觉变得迟钝，可在这样的夜晚，他还是想念父母想得厉害。深挖他们的死亡，是一种痛苦却又忍不住的冲动。大多数人都对超级英雄着迷——显然，占 96%——所以能找到的信息很多。</p><p>奥尔登开始学着区分事实与虚构。那天在医院里，汉娜没有骗他，这一点帮了大忙。她告诉他的那些事成了路标，让他得以找到这件事的其他碎片。</p><p>那些更加丑陋的碎片。</p><p>比如，网上有一些躯体榨取者受害人的照片。他们看起来，比通常的尸体还要更死气沉沉。他们的身体扭曲着，惨不忍睹。不过，躯体榨取者本人的照片，却全都是好看的——学校拍的照片里，一个脸色苍白的男孩穿着衬衫，打着领带，带着笑容。</p><p>超人类通常在十五岁到十七岁之间获得能力。他杀死二十七个人的时候，还是个高中毕业班的学生。大多数死亡发生在夜店，但在那之前也有几个。英雄追击途中，又有三个人死去。</p><p>等他被逼进奥尔登卧室街对面的那栋楼之后，死亡人数要么是零，要么是两个。取决于你怎么看。有些网站把奥尔登的父母算作躯体榨取者的受害人，另一些把他们列为旁观者。其中一个网站写出了他们的名字——理查德和莉娅·索恩——在旁边标上“附带损害”。</p><p>还有几个仇视超人类的网站，甚至把他们列为阿琼·托马斯和汉娜·埃尔伯的受害人。像是那两人故意杀了他们一样。</p><p>“想也知道，那些‘英雄’没被摄像头拍着的时候，肯定成天干这种破事，”一个叫 wakeuptheresbacon 的用户说，“随便杀两个人，这样多好掩盖。就说‘哎呀，是我打击犯罪时出了点意外’。以前我就想过好多回了。再看看这两个蠢蛋。他们肯定是英雄迷。那女的就在一家‘疗愈’院工作。”</p><p>奥尔登以前已经看过这条评论好几次了。虽然它让他愤怒不已，他还是不断回到这个网站，盯着它看。</p><p>过去三年里，他有过几个阶段，会因为英雄和躯体榨取者交手时犯了错而怨恨他们。但眼下他并不在这样的阶段里，而且，他从来没有弄不清究竟谁该负最终责任。</p><p>而现在，他只是……对 wakeuptheresbacon 愤怒得要命。他理智上知道这样很奇怪，可他觉得，自己恨这个“培根”，甚至胜过恨那个真正毁掉他生活的超级反派。</p><p>他根本不认识我爸爸妈妈。他什么都不知道。他凭什么那样说他们！我妈妈的工作很重要。</p><p>所有人都为她骄傲。疗愈院通常只有一名治疗师——一名超人类，甚至一位阿尔托纳人——再加一两个学徒，以及寥寥几名普通人类护士。那些护士必须额外接受多年的训练，获授特殊权限，才能使用某些治疗词链。</p><p>妈妈被选中做这份工作，是件了不起的大事，全家因此搬到了芝加哥。她那么出色，可培根和他那些网上的朋友，却把她说得像个傻瓜。</p><p>他怒视着屏幕，直到眼睛开始泛酸流泪。虽然那条评论已经发了一年多，他还是想告诉所有人，培根才是蠢货，可帖子已经关闭回复了。</p><p>他让额头砰地撞上桌子，开始做学校辅导员在父母去世后不久教给他的呼吸练习。他已经好几个月没想起做这个了，不过曾经有一段时间，他几乎每天都得用。他很容易就找回了节奏。</p><p>感觉好些之后，他重新坐直，把那个让人怒火中烧的网站关掉，调高耳机的音量。里面放的是他的一份暴雨声播放列表。理论上，它能帮他分散注意力，不去理会久久不退的耳鸣；但实际上，他主要拿它来盖住康妮姨妈的声音。</p><p>他输入另一个网站的名字，那是最近才找到的，然后又读了一遍。那是个叫马夫的老人的博客。老人对超级能力痴迷得近乎发烧友。</p><p>马夫把超能力的物理原理分析得细之又细。他讨论魔法与混沌之间那些复杂的相互作用，列了长篇累牍的技能清单和属性理论，还会拆解那些更鲜为人知的能力。</p><p>大部分内容奥尔登都看不懂。但老人三周前发的一篇文章，他正努力把每一处都弄明白。</p><p>那篇讲的是躯体榨取者。</p><p>而且，因为榨取者只真正出现在公众视野中过一次，整篇技能分析都以那一晚为依据。奥尔登读过好几遍，每读一遍，就感觉自己的想法稍稍移动了一点。像是在为另一种看法腾出空间，去容纳不同于那个在他心里盘踞已久的视角。</p><p>并不是马夫对那晚的事提供了多少新信息。他没有。但在讨论榨取者的能力时，他选择关注的事实，和奥尔登一直关注的那些事实，并不相同。</p><p>榨取者靠榨取别人来杀人。这一点，名字已经说得很清楚。可马夫感兴趣的是，这个反派究竟榨取了什么：</p><p>“像大多数人那样，仅仅说他偷走了受害人的力量，其实就等于说，我们根本不知道他从那些可怜人身上吸取了什么。这种说法暗示，他以某种方式夺走他人的身体能力，用来增强自己。这显然是不对的。</p><p>“这么多和我一样的超能力爱好者，竟然忽视了躯体榨取者事件中最不寻常的一点，这令我十分在意——在生命的最后时刻，他使用了官方报告仅仅称为‘类似爆炸的能量爆发’的能力。</p><p>“这和人们更常讨论的加速天赋截然不同。如果这个反派从别人身上窃取生命时，只是在增强自身的身体素质，就不可能制造‘能量爆发’。而若说除了榨取能力之外，他还从系统获得了另一项高阶技能，同样令人难以置信。</p><p>“容我提醒各位，这名反派在仅仅几周之前才成为超人类。威力巨大的技能可没那么容易到手。</p><p>“任何试图确定躯体榨取者那项致命技能真实本质的研究，都必须先对这些奇怪的爆炸做一番深入思考。</p><p>“至此，我们将进入魔法混沌那片荆棘丛生的密林。在那里，一个人或许只需把手放到另一个人身上，就能夺走比血肉筋骨更为根本的东西。”</p><p>奥尔登慢慢读完引言，又用更慢的速度读完后面的内容。马夫越写越啰嗦，丝毫没有收敛。</p><p>但对躯体榨取者爆炸能力的关注，恰好对奥尔登特别重要，所以他坚持读了下去。马夫说，榨取者曾接连引发两次爆炸。轰。轰。中间只隔了一秒。随后还有第三次，“据现场英雄报告，大约在九十秒后，也就是专注力量的蛮力者职业持有者阿琼·托马斯先生撞上他的那一刻。”</p><p>轰。</p><p>马夫好奇的是，榨取者的能力究竟是怎样制造爆炸的。</p><p>奥尔登却近乎病态地盯着时间不放。前两次和第三次之间，真的隔了九十秒吗？从爆炸把他从床上掀下来，到阿琼和反派撞穿他房间的墙、他失去意识，中间有九十秒？</p><p>自从读了那篇文章，这已经不是他第一次这样问自己。他转头看向沃米。它坐在整理得整整齐齐的床尾，旁边是他的书包。可笑眯眯的袋熊没有答案。</p><p>奥尔登闭上眼，努力回忆。他在地板上疼醒，突如其来的惊骇袭来。耳朵在嗡嗡响。他尖叫着找爸爸妈妈。</p><p>他发现自己满嘴都是血。胳膊出了问题。碎片刺进了他的身体。</p><p>他又尖叫了一声。</p><p>他看见碎玻璃。他伸手去够沃米。房间里有风。世界炸开了。</p><p>也许真有九十秒，他想。那不是很长一段时间吗？</p><p>奥尔登感觉自己的认知又在移动。他决定，一定要弄清楚。他关掉电脑，熄了灯，拿起手机爬上床。</p><p>这样太坏了。而且好丢脸。他找到手机的秒表功能，拇指悬在“开始/停止”按钮上。他小心地把手机和手藏进床单下面，深吸一口气，按下按钮。</p><p>手机传来轻微震动的那一刻，他扯着嗓子大叫：“康妮姨妈！”</p><p>一，密西西比，他在心里数。二，密西西比。</p><p>“救命！”他尖叫，“康妮姨妈！康妮姨——”</p><p>小客厅里传来仿佛一头大象横冲直撞的动静。砰的一声。一个客人骂了一句。还有像是比萨盒掉到地板上的声音。</p><p>接着，奥尔登的姨妈冲进了房间。漂染过的头发蓬乱地飞散在她脸侧。她推门用力过猛，门撞在墙上又弹了回来。她的眼睛睁得很大。</p><p>“奥尔登！”她喊着，跨过他的书包，一把抓住他，“奥尔登，宝贝！怎么了？！”</p><p>她的反应太猛烈，他差点忘了按下秒表按钮。也许我不用叫得那么大声？</p><p>“我……我好像做噩梦了。”</p><p>美发店的何塞和朗达都站在卧室门口看着他。他觉得脸烧了起来。</p><p>姨妈把他紧紧抱在怀里，轻轻地前后摇晃。“没事了，”她喃喃说，“没事了。我在这儿。”</p><p>藏在床单下面的秒表，停在八秒。</p><hr><p>奥尔登费了好大工夫，才说服姨妈自己没事，也不需要她像哄小孩子那样，陪他睡、替他吓跑怪物。</p><p>不过，他大概说服得并不成功。第二天放学，校车把他送回家后，他发现房间闻起来像是有人往里面倒了一卡车苹果派馅。他四下一看，很快找到了罪魁祸首：一只圣诞主题的香薰器，插在墙上，亮着鲜艳的粉红色光。</p><p>她大概是想给我留个小夜灯。</p><p>他皱了皱鼻子，但没有拔掉插头，就当惩罚自己吓坏了她，还撒谎隐瞒原因。</p><p>他放下书包，去了厨房。至少还有几个小时，能让他独自待着。他拉开两个塞得满满的抽屉，康妮姨妈管那里叫“扁东西放的地方”。</p><p>抽屉里确实全是扁东西。外卖菜单、菜谱、散落的塔罗牌、纸板火柴夹、“我投票了”贴纸、旧信用卡、小册子、生日贺卡、零零散散的学校作业，还有更多东西。</p><p>奥尔登在那一大堆里翻找，寻找以前在某个抽屉见过的一样东西。已经是很久以前了，不过没关系。这些扁东西从来不清，只会没完没了地越攒越多。</p><p>花了将近二十分钟，他终于找到了。那是一本酒红色的小册子，介绍一个名字很乏味的“阿妮西多拉关怀基金”能提供哪些援助。</p><p>这项基金专门照顾在超人类事件中受伤的人。奥尔登翻开册子，看到一条条列出的援助项目，其中有些他自己就领过。</p><p>创伤辅导。那笔“真遗憾你现在成了孤儿”的奖学金。</p><p>甚至还有每年一次的“反派受害者”疗养营，地点在新英格兰的一处营地。他想象不出比这更糟的假期，所以康妮姨妈提议申请的时候，他拒绝了。</p><p>奥尔登感兴趣的并不是小册子本身，而是夹在里面的一小张纸。纸上写着一个电话号码，还有一句留言：</p><p>如果你或者奥尔登有任何需要，随时给我打电话。</p><p>——H. E.</p></div><hr><p><a href="https://www.royalroad.com/fiction/63759/super-supportive/chapter/1100089/three-90-seconds" target="_blank" rel="noreferrer">原文入口</a> · <a href="/books/super-supportive/">返回作品目录</a></p>',3))])}const h=r(u,[["render",d]]);export{f as __pageData,h as default};
